// Embedded GLB data so the page works from a file:// origin.
// Browsers refuse to let <model-viewer> fetch .glb files when the page
// is opened as a local file, so each model is shipped here as a base64
// data URI and reattached to its card once the DOM is ready.
window.CAD_GLB = {
  'acdcpcb': 'data:model/gltf-binary;base64,',
  'braille': 'data:model/gltf-binary;base64,',
  'flashlight': 'data:model/gltf-binary;base64,',
  'coilwinder': 'data:model/gltf-binary;base64,',
  'dronebracket': 'data:model/gltf-binary;base64,',
  'sdorganizer': 'data:model/gltf-binary;base64,',
  'waterholder': 'data:model/gltf-binary;base64,',
  'techdesign': 'data:model/gltf-binary;base64,',
};

function applyCadGlbSources() {
  document.querySelectorAll(".pcard--cad").forEach(function (card) {
    var key = card.dataset.cad;
    var mv  = card.querySelector("model-viewer.pcard__model");
    if (mv && CAD_GLB[key]) { mv.setAttribute("src", CAD_GLB[key]); }
  });
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", applyCadGlbSources);
} else {
  applyCadGlbSources();
}
